.xt-root {
  --paper: #FFFFFF;
  --ink: #0B0B0B;
  --muted: #A3A3A3;
  --sub: #8A8A8A;
  --hair: #E9E9E9;
  --tooth: 10px;

  position: relative;
  width: 320px !important;
  max-width: 100%;
  max-height: 80vh !important;
  padding: 40px 24px 30px !important;
  background: var(--paper) !important;
  box-shadow: 0 20px 50px rgba(0,0,0,.07) !important;
  font-size: 11px !important;
  font-family: "Helvetica Neue", Helvetica, Arial, "PingFang SC", sans-serif;
  color: var(--ink);
  border-radius: 0 !important;
  overflow: visible !important;
  animation: rise .8s cubic-bezier(.2,.8,.3,1) both;
}

.xt-content {
  max-height: calc(80vh - 70px) !important;
  overflow-x: hidden !important;
  overflow-y: scroll !important;
  padding: 0 !important;
  scrollbar-width: none !important;
}
.xt-content::-webkit-scrollbar { display: none !important; }

@keyframes rise {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

.xt-root::before, .xt-root::after {
  content: "" !important;
  position: absolute;
  left: 0; right: 0;
  height: var(--tooth);
  z-index: 1;
  pointer-events: none;
}
.xt-root::before {
  top: -10px;
  background: radial-gradient(circle 5px at 5px 0, transparent 98%, var(--paper) 100%) !important;
  background-size: 10px 10px !important;
}
.xt-root::after {
  bottom: -10px;
  background: radial-gradient(circle 5px at 5px 10px, transparent 98%, var(--paper) 100%) !important;
  background-size: 10px 10px !important;
}

.xt-header, .xt-avatar, .xt-name { display: none !important; }

.xt-text-brandName {
  display: block;
  text-align: center;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: .42em;
