}

/* 隐藏副标题 */
.glass-header:has(.header-profile-section) .chat-header-subtitle {
  display: none !important;
}

/* 装饰区域：三段式标签 */
.glass-header:has(.header-profile-section)::after {
  content: "Nearby       Following       Explore";
  position: absolute !important;
  left: var(--tab-offset-left) !important; /* ❎ 标签栏左偏移，在全局变量里控制（当前45px） */
  bottom: 0px !important; /* ❎ 标签栏底部位置：0px 越大越往上 */
  height: 28px !important;
  line-height: 20px !important;
  font-size: var(--tab-font-size) !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
  font-style: normal !important;
