  border: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

/* 表情替换为三杠 SVG */
.input-btn-sticker {
  width: 24px !important;
  height: 28px !important;
  min-width: 24px !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer !important;
  opacity: 1 !important;
}

.input-btn-sticker svg {
  display: none !important;
}

.input-btn-sticker::before {
  content: "" !important;
  display: block !important;
  width: 20px !important;
  height: 20px !important;
  background-color: var(--custom-sticker-icon-color) !important;
  -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 48 48' fill='none'><path d='M7.94971 11.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/><path d='M15.94971 23.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/><path d='M23.94971 35.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/></svg>") center/contain no-repeat !important;
  mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 48 48' fill='none'><path d='M7.94971 11.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/><path d='M15.94971 23.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/><path d='M23.94971 35.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/></svg>") center/contain no-repeat !important;
}

/* 独立外置动作按钮 (发送 / AI等待 / 停止生成，背景底色与大底无缝融合) */
.send-btn-custom,
.input-btn-ai,
.stop-btn-custom {
  position: absolute !important;
  right: -52px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: var(--custom-action-box-size) !important;
  height: var(--custom-action-box-size) !important;
  min-width: var(--custom-action-box-size) !important;
  min-height: var(--custom-action-box-size) !important;
  background: var(--custom-action-bg) !important;
  border: 1.5px solid var(--custom-action-border) !important;
  border-radius: var(--custom-action-radius) !important;
  box-shadow: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 0 !important;
  margin: 0 !important;
  cursor: pointer !important;
  z-index: 10 !important;
  transition: opacity 0.15s ease, transform 0.15s ease !important;
}

.send-btn-custom svg,
.input-btn-ai svg,
.stop-btn-custom svg {
  display: none !important;
}

/* 发送 / AI按键状态：折线箭头 > */
.send-btn-custom::before,
.input-btn-ai::before {
  content: "" !important;
  display: block !important;
  width: 14px !important;
  height: 14px !important;
  background-color: var(--custom-action-icon-color) !important;
  -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'><polyline points='9 18 15 12 9 6'/></svg>") center/contain no-repeat !important;
  mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'><polyline points='9 18 15 12 9 6'/></svg>") center/contain no-repeat !important;
}

/* 停止生成按键状态：小方块 ■ */
.stop-btn-custom::before {
  content: "" !important;
  display: block !important;
  width: 12px !important;
  height: 12px !important;
  background-color: var(--custom-action-icon-color) !important;
  border-radius: 2px !important;
}

/* 按压交互反馈 */
.send-btn-custom:active,
.input-btn-ai:active,
.stop-btn-custom:active,
.input-btn-sticker:active {
  transform: translateY(-50%) scale(0.92) !important;
  opacity: 0.65 !important;
}

/* ==========================================================================
   第三部分：聊天区域 (Chat Area)
   ========================================================================== */

/* 聊天区域主背景：牢固锁定大背景色，保证各层级对比稳定 */
.chat-messages-area,
.chat-messages-area[data-theme-style="qq"],
.chat-message-list-custom {
  background-color: var(--c-main-bg) !important;
}

/* 消息外层行容器间距 */
.msg-bubble-wrapper {
  margin-bottom: 6px !important;
  margin-top: 6px !important;
}

/* 连发紧凑，换人拉开 (全面覆盖 data 属性与原生分组类名) */
.msg-bubble-wrapper.is-mid,
.msg-bubble-wrapper.is-last,
.msg-bubble-wrapper:has(.mid),
.msg-bubble-wrapper:has(.last),
.msg-bubble-wrapper[data-first="false"] {
  margin-top: 2px !important;
}

.msg-bubble-wrapper.is-first,
.msg-bubble-wrapper.is-single,
.msg-bubble-wrapper:has(.first),
.msg-bubble-wrapper:has(.single),
.msg-bubble-wrapper[data-first="true"] {
  margin-top: 12px !important;
}

/* 头像外框与容器基础样式 ❎头像大小改下面的数值，当前36px */
.msg-avatar-them-container,
.msg-avatar-me-container {
  visibility: visible !important;
  display: flex !important;
}

.msg-avatar-them-inner,
.msg-avatar-me-inner,
.msg-avatar-custom,
.msg-them div[style*="width: 36px"][style*="border-radius"],
.msg-me div[style*="width: 36px"][style*="border-radius"] {
  width: 36px !important;
  height: 36px !important;
  border-radius: 30% !important;
  border: 1.5px solid var(--nq-avatar-border) !important;
  box-shadow: 0 0 0 2px #ffffff !important;
  box-sizing: border-box !important;
  overflow: hidden !important;
}

/* 气泡通用基准结构 (彻底去除阴影) */
.bubble-them-custom,
.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;
  border-radius: 6px !important;
  padding: var(--msg-bubble-padding) !important;
  font-size: var(--msg-font-size) !important;
  line-height: 1.4 !important;
  box-sizing: border-box !important;
  transform: translateZ(0) !important;
  min-height: auto !important;
  box-shadow: none !important;
}

/* 对方气泡避让间距 */
.bubble-them-custom {
  margin-left: 2px !important;
}

/* ── 对方(AI/群友)气泡：绝对闭环两层逻辑架构 (首条深，后续全部浅，告别混乱与跳色) ── */

/* 1. 兜底与后续所有消息：统统锁定第二层【极浅雾银灰】#eff1f5，无论连发多少条绝不反弹 */
.bubble-them-custom,
.msg-them .bubble-them-custom,
[data-sender="them"] .bubble-them-custom {
  background: var(--c-ai-step-follow) !important;
  color: var(--c-text-main) !important;
  border: none !important;
}

/* 2. 第一层【沉稳深银灰】#dfe2e6：通过 data 属性、原生位置类、外层类名四重最高优先级锁死第一条与独发条 */
.bubble-them-custom.first,
.bubble-them-custom.single,
[data-first="true"] .bubble-them-custom,
[data-first="true"][data-sender="them"] .bubble-them-custom,
.msg-bubble-wrapper[data-first="true"] .bubble-them-custom,
.msg-bubble-wrapper.is-first .bubble-them-custom,
.msg-bubble-wrapper.is-single .bubble-them-custom {
  background: var(--c-ai-step-1) !important;
  color: var(--c-text-main) !important;
  border: none !important;
}

/* 对方气泡小尾巴 (颜色自动同步所在气泡背景) */
.bubble-them-custom::after {
  content: "" !important;
  position: absolute !important;
  left: -3px !important;
  bottom: 28% !important;
  width: 6px !important;
  height: 6px !important;
  background-color: inherit !important;
  border-radius: 0 0 0 2px !important;
  transform: rotate(45deg) !important;
  z-index: 1 !important;
}

